/**
 * The anchor report, pinned.
 *
 * `REPORT.md` is regenerated by CI and diffed, which catches any change at all.
 * This file asserts the properties that make the report MEAN something, because
 * a golden file is equally happy with a report that has quietly stopped
 * comparing anything.
 *
 * Day 70's lesson, in a different instrument: a selection that stops
 * attributing mutants leaves every test green and every number right. The
 * equivalent failure here is a reader that starts skipping cases — the report
 * would still regenerate identically to a committed copy of itself the moment
 * the committed copy was regenerated too. So the counts are EQUALITIES and not
 * floors. Day 70 also wrote down why: `provenance.test.js` guarded 120 pairings
 * with `assert.ok(compared > 20)` and reported nothing for six days.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';

const root = new URL('../../', import.meta.url).pathname;
const anchors = JSON.parse(readFileSync(`${root}tools/anchors/out/anchors.json`, 'utf8'));
const report = JSON.parse(
  execFileSync('node', [`${root}tools/anchors/compare.mjs`, '--json'], { encoding: 'utf8' }),
);

test('the reader read every fixture file the survey names', () => {
  assert.equal(anchors.files.length, 15);
  assert.equal(anchors.counts.cases, 148);
  for (const file of anchors.files) {
    assert.match(file.sha256, /^[0-9a-f]{64}$/, `${file.path} has no content hash`);
    assert.ok(file.bytes > 0);
  }
});

test('the upstream is pinned to a commit, not a branch', () => {
  assert.match(anchors.upstream.commit, /^[0-9a-f]{40}$/);
  assert.equal(anchors.upstream.version, '2.93.3');
});

test('every kept anchor is in a year and a state the engine declares', () => {
  for (const anchor of anchors.anchors) {
    assert.ok([2025, 2026].includes(anchor.year), `${anchor.id} is outside the declared years`);
    assert.ok(anchor.expect.length > 0, `${anchor.id} asserts nothing`);
    for (const expectation of anchor.expect) {
      assert.ok(
        ['totalTax', 'taxableIncome', 'taxBeforeCredits'].includes(expectation.comparand),
        `${anchor.id} compares against ${expectation.comparand}`,
      );
    }
  }
});

test('the counts are exact, so a reader that stops reading fails here', () => {
  assert.deepEqual(
    {
      kept: anchors.counts.keptCases,
      assertions: report.counts.assertionsCompared,
      agree: report.counts.agree,
      disagree: report.counts.disagree,
      errored: report.counts.errored,
      states: report.counts.states,
      refused: anchors.counts.refused,
    },
    // 10 -> 12 ON DAY 72, and the two that closed were both Kentucky's family
    // size tax credit. One of them, `2025-KY-ky-18`, was labelled by the
    // UPSTREAM FIXTURE as the combined-separate election "preserving the age-65
    // credit", and this package copied that cause into a shipped note. It was
    // wrong: the household now agrees to the cent with the election still
    // unmodelled, so the election costs it nothing. A disagreement's NUMBER can
    // be measured and its CAUSE cannot.
    { kept: 13, assertions: 14, agree: 12, disagree: 2, errored: 0, states: 6, refused: 2 },
  );
});

test('the states that agree are named, so losing one is not absorbed by a total', () => {
  assert.deepEqual(report.agreeingStates, ['AR', 'KY', 'NM', 'SC', 'UT', 'VA']);
});

test('New Mexico reproduces TaxAct PIT-1 on the household Day 67 settled the state with', () => {
  const rows = report.rows.filter((row) => row.id === '2025-NM-nm-3');
  assert.equal(rows.length, 2);
  const taxable = rows.find((row) => row.comparand === 'taxableIncome');
  const before = rows.find((row) => row.comparand === 'taxBeforeCredits');
  // PIT-1 line 17 and line 22, as the fixture's own comment records them.
  assert.equal(taxable.expected, 882_064);
  assert.equal(before.expected, 49_400);
  assert.ok(Math.abs(taxable.difference) <= 1, `taxable income is off by ${taxable.difference}`);
  assert.ok(Math.abs(before.difference) <= 1, `tax before credits is off by ${before.difference}`);
});

test("Virginia reproduces the Form 760 spouse-tax-adjustment worksheet to the cent", () => {
  const row = report.rows.find((r) => r.id === '2025-VA-va-4');
  assert.equal(row.expected, 5795.24);
  assert.equal(row.difference, 0);
  // AND THE AGREEMENT IS DECLARED INCOMPLETE. The first version of `ours.mjs`
  // reached 5785.66 here by passing a figure into a field documented as line 5
  // of that worksheet; this assertion exists so that the limitation cannot be
  // dropped without the test noticing, because dropping it would turn a
  // narrower claim into a broader one with no change to any number.
  assert.equal(row.limitation, "Virginia's spouse tax adjustment is not claimed");
});

test('every refusal names the household fact that caused it', () => {
  assert.equal(anchors.refused.length, 2);
  for (const refusal of anchors.refused) {
    assert.ok(refusal.problems.length > 0, `${refusal.ref} refuses without saying why`);
    for (const problem of refusal.problems) {
      assert.match(problem, /rule [13]$/, `"${problem}" does not name the rule it broke`);
    }
  }
  // Both refusals are one missing input, and naming it here is what keeps it on
  // the worklist: a childcare-expense field would unlock a TaxAct-anchored
  // Colorado household and an Iowa one.
  assert.ok(anchors.refused.every((r) => r.problems.some((p) => p.includes('tax_unit_childcare_expenses'))));
});
